const a = require('fs').readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const sum = a.reduce((s, x) => s + x, 0);

if (sum % 3 !== 0) {
  console.log('N');
} else {
  const target = sum / 3;
  let possible = false;

  for (let i = 0; i < 6; i++) {
    if (a[i] !== target) continue;
    for (let j = 0; j < 6; j++) {
      for (let k = j + 1; k < 6; k++) {
        if (j !== i && k !== i && a[j] + a[k] === target) {
          possible = true;
        }
      }
    }
  }

  console.log(possible ? 'S' : 'N');
}
